#!/usr/bin/env python3
"""Admit one original-response accounting receiving operation."""
from __future__ import annotations
import argparse
import hashlib
import json
import os
from pathlib import Path
import sys

OPERATIONS = {"scf-node-operation-accounting-free-a39c-20261012",
              "scf-node-operation-accounting-free-02-a39c-20261012"}
INTENT = "scf-opencage-native-customer-a39c-20261011"
RECEIVER = json.loads("\"import {readFile,lstat,realpath,mkdir,open,link,unlink} from 'node:fs/promises';\\nimport {createHash,randomUUID} from 'node:crypto';\\nimport {resolve,join,dirname} from 'node:path';\\nimport {execFile} from 'node:child_process';\\nimport {promisify,isDeepStrictEqual} from 'node:util';\\nconst exec=promisify(execFile),hash=raw=>createHash('sha256').update(raw).digest('hex');\\nconst need=(ok,code)=>{if(!ok)throw new Error(code);};\\nconst json=value=>Buffer.from(JSON.stringify(value,null,2)+'\\\\n');\\nconst [inputPath,inputSha256]=process.argv.slice(1);\\nneed(inputPath&&/^[a-f0-9]{64}$/.test(inputSha256??''),'RECEIVING_INPUT_REQUIRED');\\nconst inputRaw=await readFile(inputPath);need(hash(inputRaw)===inputSha256,'RECEIVING_INPUT_CHANGED');\\nconst input=JSON.parse(inputRaw);need(input.schema==='commons.scf-node-accounting-receiving/v1','RECEIVING_SCHEMA');\\nconst root=resolve(input.project),out=resolve(root,input.outputDirectory??'run');\\nneed(out.startsWith(root+'/'),'RECEIVING_OUTPUT_PATH_REQUIRED');\\nneed(root===input.project&&await realpath(root)===root,'RECEIVING_PROJECT_CHANGED');\\nconst manifestRaw=await readFile(input.sourceManifest),manifest=JSON.parse(manifestRaw);\\nneed(hash(manifestRaw)===input.sourceManifestSha256&&manifest.project===root,'RECEIVING_SOURCE_MANIFEST_CHANGED');\\nfor(const file of manifest.files){\\n const path=resolve(root,file.path);need(path.startsWith(root+'/')&&await realpath(path)===path,'RECEIVING_SOURCE_PATH');\\n const stat=await lstat(path),raw=await readFile(path);\\n need(stat.isFile()&&!stat.isSymbolicLink()&&raw.length===file.bytes&&hash(raw)===file.sha256,'RECEIVING_SOURCE_CHANGED');\\n const git=createHash('sha1').update(Buffer.from('blob '+raw.length+'\\\\0')).update(raw).digest('hex');\\n need(git===file.gitBlob,'RECEIVING_GIT_SOURCE_CHANGED');\\n}\\nfor(const file of Object.values(manifest.runtimePeers.packages)){\\n const raw=await readFile(file.path);need(hash(raw)===file.sha256,'RECEIVING_DEPENDENCY_CHANGED');\\n}\\nneed(await realpath(input.node)===input.node,'RECEIVING_NODE_CHANGED');\\nneed(await realpath(input.runtimeDirectory)===input.runtimeDirectory,'RECEIVING_FINANCIAL_RUNTIME_CHANGED');\\nconst originals=[];\\nfor(const file of input.original.files){\\n const raw=await readFile(file.path);need(raw.length===file.bytes&&hash(raw)===file.sha256,'ORIGINAL_BUYER_SOURCE_CHANGED');\\n originals.push({file,raw});\\n}\\nconst meta=JSON.parse(originals.find(x=>x.file.kind==='operation').raw);\\nconst cfg=JSON.parse(originals.find(x=>x.file.kind==='configuration').raw);\\nconst attempt=JSON.parse(originals.find(x=>x.file.kind==='attempt').raw);\\nneed(meta.intentId===input.intentId&&meta.runtimeDirectory===input.original.producerRuntimeDirectory&&\\n meta.configSha256===input.original.configurationSha256&&attempt.exitCode===0&&\\n cfg.operation.intentId===input.intentId&&cfg.operation.expect.maxAtomic==='0','ORIGINAL_UNPAID_ATTEMPT_CHANGED');\\nawait mkdir(out,{recursive:true,mode:0o700});need(await realpath(out)===out,'RECEIVING_OUTPUT_CHANGED');\\nasync function retain(path,raw){\\n try{need((await readFile(path)).equals(raw),'RECEIVING_OUTPUT_CONFLICT');return;}catch(error){if(error.code!=='ENOENT')throw error;}\\n const temp=path+'.tmp-'+randomUUID();let handle;\\n try{\\n  handle=await open(temp,'wx',0o600);await handle.writeFile(raw);await handle.sync();await handle.close();handle=null;\\n  try{await link(temp,path);}catch(error){if(error.code!=='EEXIST')throw error;need((await readFile(path)).equals(raw),'RECEIVING_OUTPUT_CONFLICT');}\\n  const parent=await open(dirname(path),'r');try{await parent.sync();}finally{await parent.close();}\\n }finally{if(handle)await handle.close();await unlink(temp).catch(error=>{if(error.code!=='ENOENT')throw error;});}\\n}\\n\\nasync function selected(descriptor){\\n need(descriptor&&typeof descriptor.path==='string'&&resolve(descriptor.path)===descriptor.path&&\\n  await realpath(descriptor.path)===descriptor.path,'CONTINUATION_SOURCE_PATH');\\n const st=await lstat(descriptor.path),raw=await readFile(descriptor.path);\\n need(st.isFile()&&!st.isSymbolicLink()&&raw.length===descriptor.bytes&&\\n  hash(raw)===descriptor.sha256,'CONTINUATION_SOURCE_CHANGED');\\n return raw;\\n}\\nasync function previousReceiving(){\\n const prior=input.previousReceiving;\\n if(prior===undefined)return null;\\n need(prior.reason==='SELECTED_FINANCIAL_NETWORKS_ASSET_MISSING'&&\\n  prior.operationId==='scf-node-operation-accounting-free-a39c-20261012'&&\\n  input.operationId==='scf-node-operation-accounting-free-02-a39c-20261012'&&\\n  prior.commandId==='finalize-Hoj0mD','CONTINUATION_SELECTION_REQUIRED');\\n const saved=[];\\n const read=async(descriptor,name)=>{const raw=await selected(descriptor);saved.push({name,raw});return raw;};\\n const oldInputRaw=await read(prior.input,'Prior_Receiving_Input.json'),oldInput=JSON.parse(oldInputRaw);\\n const oldManifestRaw=await read(prior.sourceManifest,'Prior_Source_Manifest.json'),oldManifest=JSON.parse(oldManifestRaw);\\n need(oldInput.operationId===prior.operationId&&oldInput.project===root&&\\n  oldInput.intentId===input.intentId&&oldInput.stateDirectory===input.stateDirectory&&\\n  isDeepStrictEqual(oldInput.original,input.original)&&oldInput.example===input.example&&\\n  oldInput.sourceManifest===prior.sourceManifest.path&&\\n  oldInput.sourceManifestSha256===hash(oldManifestRaw)&&oldManifest.project===root,\\n  'CONTINUATION_ORIGINAL_RECEIVING_CHANGED');\\n const native={};\\n for(const name of ['request','result','artifacts']){\\n  need(prior.native[name].path===join(prior.native.directory,name+'.json'),'CONTINUATION_NATIVE_PATH');\\n  native[name]=JSON.parse(await read(prior.native[name],'Prior_Native_'+name+'.json'));\\n }\\n const originalCommand=native.request.intent?.command;\\n need(prior.native.directory===join(root,'native',hash(prior.operationId))&&\\n  native.request.intent.operation_id===prior.operationId&&native.request.intent.project===root&&\\n  Array.isArray(originalCommand)&&originalCommand.length===6&&\\n  originalCommand[0]===input.node&&originalCommand[1]==='--input-type=module'&&originalCommand[2]==='-e'&&\\n  hash(Buffer.from(originalCommand[3]))===prior.receiverSha256&&\\n  originalCommand[4]===prior.input.path&&originalCommand[5]===hash(oldInputRaw)&&\\n  native.result.state==='failed'&&native.result.exit_code===1&&native.result.stop_requested===false&&\\n  Array.isArray(native.artifacts.files)&&native.artifacts.errors.length===0&&\\n  native.result.artifacts.files===native.artifacts.files.length&&\\n  native.result.artifacts.bytes===native.artifacts.files.reduce((n,f)=>n+f.bytes,0),\\n  'CONTINUATION_ORIGINAL_NATIVE_REQUIRED');\\n for(const file of native.artifacts.files){\\n  need(typeof file.path==='string'&&resolve(root,file.path).startsWith(root+'/'),'CONTINUATION_NATIVE_ARTIFACT_PATH');\\n  await selected({path:resolve(root,file.path),bytes:file.bytes,sha256:file.sha256});\\n }\\n for(const descriptor of [prior.input,prior.sourceManifest]){\\n  const matches=native.artifacts.files.filter(f=>resolve(root,f.path)===descriptor.path);\\n  need(matches.length===1&&matches[0].bytes===descriptor.bytes&&\\n   matches[0].sha256===descriptor.sha256,'CONTINUATION_NATIVE_SOURCE_NOT_SELECTED');\\n }\\n const command={};\\n need(prior.commandDirectory===join(input.original.operationDirectory,'accounting',prior.commandId),\\n  'CONTINUATION_ACCOUNTING_PATH');\\n for(const name of ['context.json','completion.json','invocation.json','process.json',\\n                    'attempt-source.json','evidence-source.json','stdout.json','stderr.log']){\\n  const descriptor=prior.commandFiles[name];\\n  need(descriptor.path===join(prior.commandDirectory,name),'CONTINUATION_COMMAND_PATH');\\n  const raw=await read(descriptor,'Prior_Accounting_'+name);\\n  command[name]=name==='stdout.json'||name==='stderr.log'?raw:JSON.parse(raw);\\n }\\n const context=command['context.json'],completion=command['completion.json'];\\n need(context.schema==='stellar-forge.node-operation-accounting-command.v1'&&\\n  context.commandId===prior.commandId&&context.commandDirectory===prior.commandDirectory&&\\n  context.identity.intentId===input.intentId&&context.identity.operationDirectory===input.original.operationDirectory&&\\n  context.identity.producerRuntimeDirectory===input.original.producerRuntimeDirectory&&\\n  context.identity.configurationSha256===input.original.configurationSha256&&\\n  context.execution.runtimeDirectory===oldInput.runtimeDirectory&&\\n  context.execution.node===input.node&&context.request.workspaceDirectory===null&&\\n  context.request.outboxDirectory===null&&context.request.merchantRoute===null&&\\n  completion.schema===context.schema&&completion.contextSha256===hash(json(context))&&\\n  completion.process.exitCode===2&&completion.process.exitSignal===null&&\\n  completion.process.errorCode==='ENOENT'&&completion.output===null&&\\n  Number.isFinite(Date.parse(completion.completedAt))&&\\n  command['stdout.json'].length===0&&\\n  JSON.parse(command['stderr.log'].toString('utf8').trim()).error==='ENOENT',\\n  'CONTINUATION_ENDED_ACCOUNTING_REQUIRED');\\n const invocation=command['invocation.json'];\\n need(Array.isArray(invocation.command)&&invocation.command.length===6&&\\n  invocation.command[0]===input.node&&invocation.command[1]===context.execution.worker.path&&\\n  invocation.command[2]==='--context'&&invocation.command[3]===join(prior.commandDirectory,'context.json')&&\\n  invocation.command[4]==='--context-sha256'&&invocation.command[5]===hash(json(context))&&\\n  invocation.commandSha256===hash(json(invocation.command))&&command['process.json'].pid>0,\\n  'CONTINUATION_ORIGINAL_ACCOUNTING_COMMAND_CHANGED');\\n for(const kind of ['operation','configuration','attempt','evidence']){\\n  const file=input.original.files.find(f=>f.kind===kind);\\n  need(context.source[kind].path===file.path&&context.source[kind].bytes===file.bytes&&\\n   context.source[kind].sha256===file.sha256,'CONTINUATION_ACCOUNTING_SOURCE_CHANGED');\\n }\\n need(isDeepStrictEqual(command['attempt-source.json'],attempt)&&\\n  isDeepStrictEqual(command['evidence-source.json'],JSON.parse(originals.find(x=>x.file.kind==='evidence').raw)),\\n  'CONTINUATION_ACCOUNTING_SNAPSHOT_CHANGED');\\n const asset='stellar/scf-starforge-20261009/sf86-rpc-transfer-reconcile/networks.json';\\n const newer=new Map(manifest.files.map(f=>[f.path,f]));\\n need(newer.size===manifest.files.length&&oldManifest.files.length+1===manifest.files.length,\\n  'CONTINUATION_IMPLEMENTATION_INVENTORY_CHANGED');\\n for(const old of oldManifest.files){\\n  const replacement=old.path.startsWith('financial-source/')?\\n   'financial-source-02/'+old.path.slice('financial-source/'.length):old.path;\\n  const current=newer.get(replacement);\\n  need(current&&current.gitBlob===old.gitBlob&&current.sha256===old.sha256&&\\n   current.bytes===old.bytes&&current.sourcePath===old.sourcePath&&\\n   current.sourceCommit===old.sourceCommit,'CONTINUATION_IMPLEMENTATION_REPLACED');\\n  await selected({path:resolve(root,old.path),bytes:old.bytes,sha256:old.sha256});\\n }\\n const addition=newer.get('financial-source-02/'+asset);\\n need(addition?.gitBlob==='2f92b8e3f8498fd07136c7f9b741c9e8fe3c3aa8'&&\\n  addition.sourceCommit==='b52c196dbeb270aa0ea16eaf95d8f6a4770f86e4'&&\\n  addition.sourcePath===asset&&input.runtimeDirectory===resolve(root,\\n   'financial-source-02/stellar/scf-starforge-20261009/sf88-operator-buyer-cli'),\\n  'CONTINUATION_ORIGINAL_NETWORK_ASSET_REQUIRED');\\n try{await lstat(resolve(oldInput.runtimeDirectory,'../sf86-rpc-transfer-reconcile/networks.json'));\\n  throw new Error('CONTINUATION_FAILED_INSTALLATION_CHANGED');}\\n catch(error){if(error.code!=='ENOENT')throw error;}\\n const originalTerms=context.execution.originalSource.find(f=>f.path===resolve(oldInput.runtimeDirectory,\\n  '../sf86-rpc-transfer-reconcile/terms.mjs'));\\n need(originalTerms&&hash(await selected(originalTerms))===originalTerms.sha256,\\n  'CONTINUATION_ORIGINAL_TERMS_CHANGED');\\n const report={schema:'commons.scf-node-accounting-receiving-continuation/v1',\\n  reason:prior.reason,previousOperationId:prior.operationId,previousNativeDirectory:prior.native.directory,\\n  previousCommandId:prior.commandId,previousCommandDirectory:prior.commandDirectory,\\n  previousContextSha256:hash(json(context)),previousCompletionSha256:prior.commandFiles['completion.json'].sha256,\\n  previousInputSha256:hash(oldInputRaw),previousSourceManifestSha256:hash(oldManifestRaw),\\n  selectedSourceManifestSha256:input.sourceManifestSha256,selectedAsset:addition,\\n  originalAttemptSha256:input.original.files.find(f=>f.kind==='attempt').sha256,\\n  originalEvidenceSha256:input.original.files.find(f=>f.kind==='evidence').sha256,\\n  action:'NEW_ACCOUNTING_COMMAND_FOR_SAME_ORIGINAL_FREE_RESPONSE'};\\n for(const file of saved)await retain(join(out,file.name),file.raw);\\n await retain(join(out,'Receiving_Continuation.json'),json(report));\\n return{report,files:[...saved.map(f=>f.name),'Receiving_Continuation.json'],context};\\n}\\n\\nconst controller=new AbortController(),abort=()=>controller.abort();\\nprocess.once('SIGTERM',abort);process.once('SIGINT',abort);\\nconst shared=['--runtime',input.runtimeDirectory,'--state',input.stateDirectory,'--intent',input.intentId];\\nasync function run(action,args=[]){\\n const result=await exec(input.node,[input.example,action,...shared,...args],{\\n  cwd:root,encoding:'utf8',maxBuffer:4194304,timeout:480000,signal:controller.signal});\\n return JSON.parse(result.stdout);\\n}\\ntry{\\n const continuation=await previousReceiving();\\n const prior=await run('recover');\\n let result=prior?.lastComplete??null;\\n if(!result){\\n  if(continuation){\\n   need(prior?.latest?.commandId===input.previousReceiving.commandId&&\\n    prior.latest.status==='NO_COMPLETE_OUTPUT'&&prior.latest.result===null&&\\n    prior.latest.process.exitCode===2&&prior.latest.process.errorCode==='ENOENT',\\n    'ORIGINAL_ACCOUNTING_COMMAND_REQUIRES_RECONCILIATION');\\n  }else need(prior===null,'ORIGINAL_ACCOUNTING_COMMAND_REQUIRES_RECONCILIATION');\\n  result=await run('finalize');\\n }\\n need(result.native.kind==='UNPAID_RESPONSE'&&result.native.result.outcome==='NO_PAYMENT_REQUIRED'&&\\n result.native.approvedRequestSha256===null&&result.native.recordAuthority==='ORIGINAL_UNSIGNED_RESPONSE',\\n 'ORIGINAL_UNPAID_ACCOUNTING_RESULT_REQUIRED');\\n need(result.native.identity.intentId===input.intentId&&\\n result.native.identity.producerRuntimeDirectory===input.original.producerRuntimeDirectory&&\\n result.native.accountingRuntimeDirectory===input.runtimeDirectory&&\\n result.native.identity.configurationSha256===input.original.configurationSha256,\\n 'ACCOUNTING_SOURCE_IDENTITY_CHANGED');\\n const view=await run('recover',['--command',result.commandId]);\\n need(view?.latest?.commandId===result.commandId&&view.latest.result&&\\n isDeepStrictEqual(view.latest.result.native,result.native),'ACCOUNTING_REOPEN_CHANGED');\\n const exportPath=join(out,'Operation_Accounting.json');\\n let exported;\\n try{\\n  const raw=await readFile(exportPath);exported={path:exportPath,bytes:raw.length,sha256:hash(raw)};\\n }catch(error){if(error.code!=='ENOENT')throw error;\\n  exported=await run('export',['--command',result.commandId,'--output',exportPath]);}\\n const exportRaw=await readFile(exportPath),document=JSON.parse(exportRaw);\\n need(exportRaw.length===exported.bytes&&hash(exportRaw)===exported.sha256&&\\n document.schema==='stellar-forge.node-operation-accounting-export.v1'&&\\n document.intentId===input.intentId&&document.commandId===result.commandId&&\\n isDeepStrictEqual(document.result.native,result.native)&&\\n document.contextSha256===result.native.contextSha256&&\\n hash(json(document.context))===result.native.contextSha256,'ACCOUNTING_EXPORT_CHANGED');\\n for(const name of ['attempt','evidence']){\\n  const original=input.original.files.find(f=>f.kind===name),saved=document.source[name],raw=Buffer.from(saved.base64,'base64');\\n  need(saved.base64===raw.toString('base64')&&raw.length===original.bytes&&\\n   hash(raw)===original.sha256&&saved.bytes===original.bytes&&saved.sha256===original.sha256,\\n   'ACCOUNTING_EXPORTED_ORIGINAL_CHANGED');\\n }\\n for(const {file,raw} of originals){\\n  need((await readFile(file.path)).equals(raw),'ORIGINAL_BUYER_SOURCE_MUTATED');\\n  await retain(join(out,file.outputName),raw);\\n }\\n await retain(join(out,'Source_Manifest.json'),manifestRaw);\\n await retain(join(out,'Accounting_View.json'),json(view));\\n const files=[];\\n for(const name of [...input.original.files.map(f=>f.outputName),'Source_Manifest.json','Accounting_View.json','Operation_Accounting.json',...(continuation?.files??[])]){\\n  const raw=await readFile(join(out,name));files.push({path:name,bytes:raw.length,sha256:hash(raw)});\\n }\\n const report={schema:'commons.scf-node-accounting-receiving-result/v1',state:'COMPLETE',\\n  operationId:input.operationId,intentId:input.intentId,inputSha256,sourceManifestSha256:input.sourceManifestSha256,\\n  sourceSelections:manifest.sourceSelections,original:input.original,continuation:continuation?.report??null,accounting:{\\n   commandId:result.commandId,commandDirectory:result.commandDirectory,kind:result.native.kind,\\n   outcome:result.native.result.outcome,authority:result.native.recordAuthority,\\n   producerRuntimeDirectory:result.native.identity.producerRuntimeDirectory,\\n   selectedRuntimeDirectory:result.native.accountingRuntimeDirectory,\\n   completedAt:result.native.completedAt},stages:['original-source','finalize-existing-attempt',\\n   'new-process-reopen','private-complete-export','original-bytes-preserved'],files};\\n await retain(join(out,'Accounting_Receiving.json'),json(report));\\n const reopened=JSON.parse(await readFile(join(out,'Accounting_Receiving.json')));\\n need(isDeepStrictEqual(reopened,report),'RECEIVING_REOPEN_CHANGED');\\n process.stdout.write(JSON.stringify({state:'COMPLETE',operationId:input.operationId,intentId:input.intentId,\\n  commandId:result.commandId,outcome:result.native.result.outcome,files:files.length,\\n  report:join(out,'Accounting_Receiving.json')})+'\\\\n');\\n}finally{\\n process.removeListener('SIGTERM',abort);process.removeListener('SIGINT',abort);\\n}\\n\"")

def directory(value):
    p = Path(value).absolute()
    if p.resolve(strict=True) != p or not p.is_dir():
        raise ValueError("Use a canonical existing directory")
    return p

def regular(value):
    p = Path(value).absolute()
    if p.resolve(strict=True) != p or p.is_symlink() or not p.is_file():
        raise ValueError("Use a canonical original file")
    return p

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("input", "input-sha256", "host-root", "records-root", "peer", "worker-root", "temp-root"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args()
    input_path = regular(args.input)
    raw = input_path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != args.input_sha256:
        raise ValueError("The selected original receiving input changed")
    value = json.loads(raw)
    if (value.get("schema") != "commons.scf-node-accounting-receiving/v1"
            or value.get("operationId") not in OPERATIONS or value.get("intentId") != INTENT):
        raise ValueError("Select this original completed free response")
    operation_id = value["operationId"]
    project = directory(value["project"])
    node = regular(value["node"])
    manifest = regular(value["sourceManifest"])
    if hashlib.sha256(manifest.read_bytes()).hexdigest() != value["sourceManifestSha256"]:
        raise ValueError("The selected implementation manifest changed")
    selected = json.loads(manifest.read_bytes())
    if selected.get("project") != str(project):
        raise ValueError("The implementation manifest belongs to another project")
    example = regular(value["example"])
    source = directory(project / "source")
    continuation = operation_id == "scf-node-operation-accounting-free-02-a39c-20261012"
    financial_name = "financial-source-02" if continuation else "financial-source"
    financial_source = directory(value.get("financialSourceDirectory", str(project / "financial-source")))
    if financial_source != project / financial_name:
        raise ValueError("Select the exact original or complete successor financial directory")
    output_name = "run-02" if continuation else "run"
    if value.get("outputDirectory", "run") != output_name:
        raise ValueError("Preserve the receiving operation's own output directory")
    if continuation != (value.get("previousReceiving") is not None):
        raise ValueError("The receiving successor requires the original failed-command selection")
    previous_financial_source = directory(project / "financial-source")
    runtime = directory(value["runtimeDirectory"])
    state = directory(value["stateDirectory"])
    producer = directory(value["original"]["producerRuntimeDirectory"])
    for p in (input_path, manifest, example, runtime):
        if p == project or not p.is_relative_to(project):
            raise ValueError("Keep the receiving implementation and input in the selected project")
    if not example.is_relative_to(source) or not runtime.is_relative_to(financial_source):
        raise ValueError("Preserve the selected SDK and original financial runtime")
    operation = directory(value["original"]["operationDirectory"])
    if operation.parent != state or operation.name != hashlib.sha256(INTENT.encode()).hexdigest():
        raise ValueError("Preserve the original Buyer operation directory")
    host = directory(args.host_root)
    sys.path.insert(0, str(host))
    from native_foreground import ForegroundLaunch, load_native
    native = load_native(host)
    dependencies = directory(selected["runtimePeers"]["dependencyRoot"])
    command = [str(node), "--input-type=module", "-e", RECEIVER, str(input_path), args.input_sha256]
    values = argparse.Namespace(
        operation_id=operation_id, peer=args.peer, project=str(project),
        command=command, java=None, node=None,
        artifact=[input_path.relative_to(project).as_posix(), manifest.relative_to(project).as_posix()],
        artifact_on_success=[output_name],
        artifact_on_failure=[output_name],
        retain_artifacts=True, records_root=str(Path(args.records_root).resolve()),
        worker_root=str(directory(args.worker_root)), temp_root=str(directory(args.temp_root)),
        runtime_path=sorted({str(host), str(source), str(financial_source), str(previous_financial_source), str(node),
                             str(producer), str(state), str(dependencies)}),
        runtime_consumers_root=None, memory_mib=256, memory_reserve_mib=64,
        memory_reservations_root=None, memory_reclaim="clean-cache", memory_storage="included",
        disk_space=[str(project)+"=2", str(state)+"=2"],
        disk_inodes=[str(project)+"=128", str(state)+"=128"],
        disk_reserve_mib=1, disk_reserve_inodes=64, disk_reservations_root=None,
    )
    launch = ForegroundLaunch(native)
    report = native.start(values, launcher=launch)
    print(json.dumps({"operation_id":operation_id,
                      "record":str(native.run_path(operation_id, args.records_root)),
                      "input_sha256":args.input_sha256,
                      "receiver_sha256":hashlib.sha256(RECEIVER.encode()).hexdigest(),
                      "original_native":report}), flush=True)
    if launch.root is not None:
        return launch.handoff()
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
